import re, sys
from pathlib import Path
bad = []
for f in sys.argv[1:]:
    p = Path(f); text = p.read_text()
    for target in re.findall(r"\]\(([^)\s]+)\)", text):
        if re.match(r"[a-z]+:", target) or target.startswith("#"):
            continue
        if not (p.parent / target.split("#")[0]).exists():
            bad.append((f, target))
    lines = text.splitlines()
    for i, line in enumerate(lines):
        if line.startswith("|") and i > 0 and not lines[i - 1].startswith("|"):
            width = line.count("|")
            j = i
            while j < len(lines) and lines[j].startswith("|"):
                if lines[j].replace("\\|", "").count("|") != width:
                    bad.append((f, f"table row {j + 1}: {lines[j].count('|')} pipes, header {width}"))
                j += 1
print("broken links / ragged tables:", bad or "none")
EOF
